mapper.select:
WITH PS AS ( SELECT p.emp_id, SUM(CASE WHEN NVL(i.is_previous,'N') = 'N' THEN i.amount ELSE 0 END) AS pay_tot_amt, SUM(CASE WHEN NVL(i.is_previous,'N') = 'Y' THEN i.amount ELSE 0 END) AS prev_pay_tot_amt, (SELECT NVL(SUM(d.amount),0) FROM payslip_deduction d WHERE d.payslip_id = p.payslip_id) AS ded_tot_amt, p.net_pay_amt, p.payslip_id FROM payslip p LEFT JOIN payslip_item i ON i.payslip_id = p.payslip_id WHERE p.apply_yyyymm = #{yyyymm} GROUP BY p.emp_id, p.net_pay_amt, p.payslip_id ), YH AS ( SELECT emp_id, tax_apply_type FROM ( SELECT y.emp_id, y.tax_apply_type, ROW_NUMBER() OVER (PARTITION BY y.emp_id ORDER BY y.created_at DESC) rn FROM yrt_header y WHERE y.base_year = TO_NUMBER(SUBSTR(#{yyyymm},1,4)) ) WHERE rn = 1 ) SELECT e.emp_no AS empNo, e.emp_name AS empName, d.dept_name AS deptName, yh.tax_apply_type AS taxApplyType, etp.tax_adjust_rate AS taxAdjustRate, etp.project_name AS projectName, NVL(etp.tax_calc_exempt_yn,'N') AS taxCalcExemptYn, NVL(etp.prorate_yn,'N') AS prorateYn, NVL(etp.settlement_reflect_yn,'N') AS settlementReflectYn, NVL(etp.manuf_tax_exempt_yn,'N') AS manufTaxExemptYn, NVL(etp.overseas_tax_exempt_yn,'N') AS overseasTaxExemptYn, NVL(etp.researcher_tax_exempt_yn,'N') AS researcherTaxExemptYn, etp.income_tax_reduction_rate AS incomeTaxReductionRate, etp.personal_tax_apply_type AS personalTaxApplyType, etp.bonus_rate AS bonusRate, NVL(ps.pay_tot_amt,0) AS payTotAmt, NVL(ps.prev_pay_tot_amt,0) AS prevPayTotAmt, NVL(ps.ded_tot_amt,0) AS dedTotAmt, NVL(ps.net_pay_amt,0) AS netPayAmt, CASE WHEN e.retire_date IS NOT NULL AND e.retire_date <= LAST_DAY(TO_DATE(#{yyyymm}||'-01','YYYY-MM-DD')) THEN 'Y' ELSE 'N' END AS retireYn FROM emp e JOIN dept d ON d.dept_id = e.dept_id LEFT JOIN PS ps ON ps.emp_id = e.emp_id LEFT JOIN emp_tax_profile etp ON etp.emp_id = e.emp_id LEFT JOIN YH yh ON yh.emp_id = e.emp_id WHERE 1=1
AND EXISTS ( SELECT 1 FROM payslip p2 WHERE p2.emp_id = e.emp_id AND p2.apply_yyyymm = #{yyyymm} AND p2.pay_type = #{payType} )
AND d.dept_code = #{deptCode}
AND e.emp_no = #{empNo}
ORDER BY e.emp_no

WITH target_ps AS ( SELECT p.payslip_id FROM payslip p JOIN emp e ON e.emp_id = p.emp_id WHERE e.emp_no = #{empNo} AND p.apply_yyyymm = #{yyyymm}
AND p.pay_type = #{payType}
) SELECT itemName, nonTaxType, previousYn, amount FROM ( SELECT i.item_name AS itemName, CAST(NULL AS VARCHAR2(30)) AS nonTaxType, NVL(i.is_previous,'N') AS previousYn, i.amount AS amount, 0 AS ord, i.item_name AS sortKey FROM payslip_item i WHERE i.payslip_id IN (SELECT payslip_id FROM target_ps)
UNION ALL
SELECT 'TOTAL' AS itemName, NULL AS nonTaxType, NULL AS previousYn, NVL(SUM(i.amount),0) AS amount, 1 AS ord, 'TOTAL' AS sortKey FROM payslip_item i WHERE i.payslip_id IN (SELECT payslip_id FROM target_ps) ) ORDER BY ord, sortKey

WITH target_ps AS ( SELECT p.payslip_id FROM payslip p JOIN emp e ON e.emp_id = p.emp_id WHERE e.emp_no = #{empNo} AND p.apply_yyyymm = #{yyyymm}
AND p.pay_type = #{payType}
) SELECT deductionName, amount FROM ( SELECT d.deduction_name AS deductionName, d.amount AS amount, 0 AS ord, d.deduction_name AS sortKey FROM payslip_deduction d WHERE d.payslip_id IN (SELECT payslip_id FROM target_ps)
UNION ALL
SELECT 'TOTAL' AS deductionName, NVL(SUM(d.amount),0) AS amount, 1 AS ord, 'TOTAL' AS sortKey FROM payslip_deduction d WHERE d.payslip_id IN (SELECT payslip_id FROM target_ps) ) ORDER BY ord, sortKey


SELECT
  NVL((
    SELECT SUM(i.amount)
      FROM payslip p
      JOIN payslip_item i ON i.payslip_id = p.payslip_id
     WHERE p.apply_yyyymm = #{yyyymm}
       AND p.pay_type = #{payType}
       AND NVL(i.is_previous,'N') = 'N'
  ),0) AS total_pay_amt,
  NVL((
    SELECT SUM(i.amount)
      FROM payslip p
      JOIN payslip_item i ON i.payslip_id = p.payslip_id
     WHERE p.apply_yyyymm = #{yyyymm}
       AND p.pay_type = #{payType}
       AND NVL(i.is_previous,'N') = 'Y'
  ),0) AS prev_paid_amt,
  NVL((
    SELECT SUM(d.amount)
      FROM payslip p
      JOIN payslip_deduction d ON d.payslip_id = p.payslip_id
     WHERE p.apply_yyyymm = #{yyyymm}
       AND p.pay_type = #{payType}
  ),0) AS total_ded_amt,
  NVL((
    SELECT SUM(p.net_pay_amt)
      FROM payslip p
     WHERE p.apply_yyyymm = #{yyyymm}
       AND p.pay_type = #{payType}
  ),0) AS net_pay_amt
FROM dual

SELECT v.voucher_id
FROM pay_voucher v
WHERE v.summary_note = #{token}

mapper.insert:
/* payslip_id 단일 건 기준: 부서별 지급/공제 사전집계 → 라인 생성 → (voucher_id, line_seq) 기준 업서트 */ MERGE INTO pay_voucher_line t USING ( WITH base AS ( SELECT p.payslip_id, e.dept_id FROM payslip p JOIN emp e ON e.emp_id = p.emp_id WHERE p.payslip_id = #{payslipId} ), i_sum AS ( /* 지급 항목 사전집계: 곱집합 방지 */ SELECT i.payslip_id, SUM(i.amount) AS pay_sum FROM payslip_item i WHERE i.payslip_id = #{payslipId} GROUP BY i.payslip_id ), d_sum AS ( /* 공제 항목 사전집계: 곱집합 방지 */ SELECT d.payslip_id, SUM(d.amount) AS ded_sum FROM payslip_deduction d WHERE d.payslip_id = #{payslipId} GROUP BY d.payslip_id ), lines AS ( /* 부서별 차변(비용) 라인 */ SELECT #{voucherId} AS voucher_id, ROW_NUMBER() OVER (ORDER BY b.dept_id) AS line_seq, #{wageAccountId} AS account_id, 'D' AS drcr_code, b.dept_id AS dept_id, NVL(i.pay_sum,0) AS debit_amt, 0 AS credit_amt FROM base b LEFT JOIN i_sum i ON i.payslip_id = b.payslip_id
UNION ALL
/* 부서별 대변(예수금) 라인: 비용 라인과 line_seq 충돌 방지를 위해 +1000 */ SELECT #{voucherId} AS voucher_id, ROW_NUMBER() OVER (ORDER BY b.dept_id) + 1000 AS line_seq, #{withholdAccountId} AS account_id, 'C' AS drcr_code, b.dept_id AS dept_id, 0 AS debit_amt, NVL(d.ded_sum,0) AS credit_amt FROM base b LEFT JOIN d_sum d ON d.payslip_id = b.payslip_id ) SELECT * FROM lines ) src ON ( t.voucher_id = src.voucher_id AND t.line_seq = src.line_seq ) WHEN MATCHED THEN UPDATE SET t.account_id = src.account_id, t.drcr_code = src.drcr_code, t.dept_id = src.dept_id, t.debit_amt = src.debit_amt, t.credit_amt = src.credit_amt WHEN NOT MATCHED THEN INSERT (line_id, voucher_id, line_seq, account_id, drcr_code, dept_id, debit_amt, credit_amt) VALUES (SEQ_PAY_VOUCHER_LINE.NEXTVAL, src.voucher_id, src.line_seq, src.account_id, src.drcr_code, src.dept_id, src.debit_amt, src.credit_amt)

