UPDATE payslip p
SET p.confirmed_yn = 'Y',
p.confirmed_at = SYSDATE
WHERE p.apply_yyyymm = #{yyyymm}
AND p.pay_type = #{payType}
AND
p.emp_id IN (
SELECT e.emp_id FROM emp e
WHERE e.emp_no IN

	#{no}

)

UPDATE payslip p
SET p.confirmed_yn = 'N',
p.confirmed_at = NULL
WHERE
p.apply_yyyymm = #{yyyymm}
AND p.pay_type = #{payType}
AND p.emp_id IN (
SELECT e.emp_id
FROM emp e
WHERE e.emp_no IN

	#{no}

)
